{"command": "cd /workspace; python3 -c "
rows=[int(l) for l in open('qr_code.txt').read().split()]
g=[[(r>>(28-i))&1 for i in range(29)] for r in rows]
def bch(d):
    v=d<<10; gen=0b10100110111
    for i in range(14,9,-1):
        if v>>i&1: v^=gen<<(i-10)
    return ((d<<10)|v)^0x5412
valid={bch(d):d for d in range(32)}
# format bits per spec, bit14..bit0
pos1=[(8,0),(8,1),(8,2),(8,3),(8,4),(8,5),(8,7),(8,8),(7,8),(5,8),(4,8),(3,8),(2,8),(1,8),(0,8)]
for inv in (0,1):
    v=0
    for k,(r,c) in enumerate(pos1):
        v|=((g[r][c]^inv))<<(14-k)
    print('inv',inv,hex(v), v in valid, valid.get(v))
    if v in valid: print('ecl/mask', valid[v]>>3, valid[v]&7)
""}

